"use client";
import Header from "@/components/Header"; import Footer from "@/components/Footer"; import {img} from "@/components/siteData";
export default function Quote(){return <><Header/><section className="quote-hero" style={{backgroundImage:`linear-gradient(90deg,rgba(0,30,70,.95),rgba(0,30,70,.45)),url("${img.infrastructure}")`}}><div><small>REQUEST A QUOTE</small><h1>REQUEST A QUOTE</h1><h2>Get a tailored solution for your project needs.</h2><p>Tell us what you need and our team will provide a customized quotation as soon as possible.</p></div></section><section className="quote-layout"><form className="quote-form" onSubmit={e=>e.preventDefault()}><h2>Inquiry Details</h2><p>Please fill out the form below. Fields with * are required.</p><div className="form-two"><input placeholder="Full Name *"/><input placeholder="Company Name *"/></div><div className="form-two"><input placeholder="Email Address *"/><input placeholder="Contact Number *"/></div><div className="form-two"><select defaultValue=""><option value="" disabled>Select project type</option><option>Infrastructure</option><option>Residential</option><option>Commercial</option><option>Agriculture</option><option>Industrial</option></select><select defaultValue=""><option value="" disabled>Select product category</option><option>HDPE</option><option>uPVC</option><option>PPR</option><option>Tanks</option><option>Drainage</option></select></div><div className="form-two"><select defaultValue=""><option value="" disabled>Select location</option><option>Luzon</option><option>Visayas</option><option>Mindanao</option></select><input type="date"/></div><textarea rows={6} placeholder="Tell us more about your requirements..."/><label className="upload">📎 Click to upload or drag and drop<small>PDF, JPG, PNG</small><input type="file"/></label><label className="checkbox"><input type="checkbox"/> I agree to be contacted by Fujipipes regarding this inquiry.</label><button className="blue-button">Submit Request →</button></form><aside className="quote-side"><div className="why-quote"><h2>Why Request a Quote?</h2><Reason icon="📄" title="Customized Quotation" text="Get a quote based on your specific needs."/><Reason icon="🎧" title="Expert Assistance" text="Our team will help you find the right products."/><Reason icon="◷" title="Fast Response" text="We aim to get back to you as soon as possible."/><Reason icon="🛡" title="Reliable Partner" text="Quality products for a stronger Philippines."/></div><div className="immediate-help"><h2>Need Immediate Assistance?</h2><strong>☎ (034) 703 8998</strong><p>Mon – Fri, 8:00 AM – 5:00 PM</p><strong>✉ sales@fujipipes.com</strong></div></aside></section><Footer/></>}
function Reason({icon,title,text}:{icon:string;title:string;text:string}){return <div className="quote-reason"><div>{icon}</div><h3>{title}</h3><p>{text}</p></div>}
